Глава I Процесс задержания
Задержание - это мера кратковременного (на срок до 2 часов) лишения человека права на свободу, которая осуществляется на основании (гл. II ч.1) Процессуального Кодекса.
Задержание не считается мерой наказания, оно носит исключительно внесудебный характер и в совокупности с другими предусмотренными законом средствами и методами позволяет сотрудникам правоохранительных органов собрать необходимые сведения (достаточную доказательственную базу) для решения вопроса о возможности или невозможности применения к лицу какой-либо ответственности.
Статья 1. Задержание подозреваемого
1.1. Лицо может быть задержано по подозрению в совершении преступления, за которое может быть назначено наказание в виде лишения свободы или штрафная санкция.
При наличии хотя бы одного из следующих оснований:
а) Когда лицо застигнуто в момент совершения преступления или непосредственно
после его совершения, сотрудником правоохранительных органов;
б) Когда на этом лице или его одежде, при нем или в его имуществе обнаружены явные следы преступления.
в) Когда 3 и более свидетелей указывают на данное лицо как на совершившее преступление.
г) Когда есть фото или видео фиксация совершенного преступления этим лицом.
д) Если имеется нормативный документ или указ уполномоченного лица.
е) Когда имеются существенные факты полагать что лицо может быть виновным в совершении преступления (схожесть фоторобота, схожесть описания предметов одежды, индивидуальные признаки лица, одинаковый номер паспорта и/или номер телефона с правонарушителем);
ж) Когда лицо застигнуто на месте совершения преступления сотрудником правоохранительных органов.
1.2. Если лицо намеренно скрывает свою личность без законных на то оснований (( ношение системной маски (/mask), либо отыгрыш РП маски )), то такое лицо может быть задержано вне хода расследования до установки личности.
1.3. Лицо может быть задержано до выяснения обстоятельств с целью получения информации, сведений, показаний по текущему уголовному производству, расследованию на срок не более 40 минут.
Статья 1.1. Порядок задержания правомочным лицом
1.1.1. При задержании лица сотруднику необходимо: представиться, предъявив удостоверение/нашивку/жетон, разъяснить основания задержания.
1.1.1.1. сотрудник ПО имеет право не представляться в следующих случаях:
а) Сотруднику угрожает опасность.
б) Задержание было произведено на территории пенитенциарного учреждения, Департамента LSPD/SFPD/LVPD, ФБР, зала Суда.
в) Массовое скопление людей (вдвое больше сотрудников проводивших процессуальные действия).
1.1.2. Сотрудник, осуществляющий задержание, по первому требованию обязан предоставить задержанному служебные документы/нашивку/жетон/бейдж, позволяющие идентифицировать личность сотрудника.
1.1.2.1. Субъекты задержания вправе потребовать у сотрудника ПО предоставить служебные документы/нашивку/жетон/бейдж, но не более чем 2 раза за весь период процесса задержания.
1.1.3. В случаях, в которых требуется доставление подозреваемого для проведения последующих процессуальных мероприятий (допрос, помещение в ИВС) сотруднику необходимо: провести первичный обыск, зачитать правила Миранды.
"Вы имеете право хранить молчание. Всё, что вы скажете, может и будет использовано против Вас. Вы имеете право на один телефонный звонок. Также Вы имеете право на адвоката. Если вам необходим адвокат, он будет для Вас запрошен. Вы понимаете свои права?"
1.1.4. Допускаются коррективы формулировки, но суть должна оставаться неизменной.
1.1.5. Субъекты задержания вправе потребовать у сотрудника ПО разъяснения его прав, но не более чем 2 раза за весь период процесса задержания.
1.1.6. В случае, если задержанный не сообщает сотруднику об ясности своих прав в течение 3-х (трёх) минут с момента вопроса сотрудника, сотрудник не обязан удостоверяться у задержанного в понимании его прав и обязан запротоколировать (зафиксировать на видеозапись) данный факт.
1.1.7. Сотрудник ПО имеет право не проводить первичный обыск в случаях если:
а) Сотруднику угрожает опасность.
б) Задержание было произведено на территории пенитенциарного учреждения, Департамента LSPD/SFPD/LVPD, ФБР, зала Суда.
в) Массовое скопление людей (вдвое больше сотрудников проводивших процессуальные действия).
Статья 1.2. Субъекты задержания
1.2.1. В процессе задержания участвуют:
а) Сотрудник или сотрудники правоохранительных органов, являющиеся непосредственными инициаторами процессуальных действий
б) Задержанный, в отношении которого проводится арест.
в) При задержании может присутствовать адвокат, заключивший письменный или устный договор об оказании юридических услуг с задержанным.
1.2.1. Никаких других третьих лиц в процессе задержания быть не может. Сотрудники правоохранительных органов вправе потребовать отойти от места задержания на 6 метров всех граждан.
Статья 1.3. Основания освобождения подозреваемого
1.3.1. Подозреваемый подлежит освобождению по решению сотрудника проводившего задержание и допрос, если:
а) не подтвердилось подозрение в совершении преступления;
б) за нарушение не предусмотрено меры пресечения в виде заключения под стражу;
в) прошло больше 2 часов с момента задержания и не была избрана мера пресечения в виде заключения под стражу.
Статья 1.4. Права задержанного:
1.4.1. Задержанный имеет право на один телефонный звонок в присутствии сотрудника. Сотрудник обязан предоставить данный звонок подозреваемому во время процесса задержания.
1.4.1.1. Длительность звонка не должна превышать 7 минут. Звонок частному или государственному адвокату также считается за потраченный телефонный звонок. Предельный срок задержания подозреваемого продлевается на количество времени, потраченного на звонок.
Примечание: Звонок считается за потраченный, при условии что собеседник поднял трубку.
Исключение: Согласие сотрудника проводящего задержание на увеличение длительности звонка.
1.4.2. Задержанный имеет право хранить молчание.
1.4.3 Задержанный имеет право на адвоката как государственного, так и частного.
Статья 1.5. Обязанности сотрудника выполняющего задержание
1.5.1.Сотрудник обязан разъяснить адвокату причины задержания.
1.5.2. Сотрудник, осуществляющий задержание, по первому требованию обязан предоставить задержанному служебные документы/нашивку/жетон/бейдж, позволяющие идентифицировать личность сотрудника.
1.5.3. задержанный вправе потребовать предоставить вышеуказанные опознавательные знаки или документы повторно, но не более чем 2 раза за весь период процесса задержания.
1.5.4 Сотрудник обязан осуществить все затребованные права задержанного и убедиться в их осуществлении.
Глава II Следствие
Статья 2. Право сотрудников и руководства организации
2.1 Право сотрудников МВД объявлять граждан в розыск до выяснения обстоятельств на основаниях, прописанных в 1.1 ПК, на срок не более 120 минут. На время подобных следственных действий лицу присваивается 6 степень розыска, после проведения которых она снимается.
2.2 Руководство организации может проводить внутренние служебные проверки и расследования по факту фабрикации уголовных дел своими сотрудниками, с последующими увольнениями, занесениями в черный список организации
Глава III Обыск
Статья 3. Личный обыск
3.1. Подозреваемый может быть подвергнут личному обыску во время задержания, ареста, чрезвычайного положения и военного положения в Федерации.
Статья 4. Обыск транспортного средства.
4.1. Сотрудник ПО имеет право обыскать транспортное средство в следующих случаях:
а) Ориентировка, иная информация, об использовании ТС или груза в противоправных целях.
б) Наличие следов преступления на транспортном средстве.
в) Задержание лица, находившегося в ТС.
г) Подтвержденный факт наличия запрещенных средств, нелегальных предметов, лиц находящихся в федеральном розыске/проходящих по уголовному делу в транспортном средстве.
Статья 5. Обыск частных территорий, помещений и зданий
5.1. Обыск частных территорий, помещений и зданий производится только при наличии ордера от Президента, Судьи, Генерального инспектора и его заместителя. Выдача ордера регулируется ФЗ “О государственной системе ордеров”
5.1.1. В исключительных случаях, когда обыск частной территории не терпит отлагательства, обыск может быть произведен на основании решения сотрудника правоохранительных органов без ордера. В этом случае, сотрудник правоохранительных органов не позднее 5 часов с момента начала производства следственного действия должен уведомить Генерального инспектора, его заместителей, или своего курирующего инспектора.
Примеры исключительных случаев для проведения обыска без ордера:
а) Человек целенаправленно скрывается от преследования в помещении.
б) Человек скрыл факт установки взрывного устройства в доме и готов его использовать.
в) Угроза безопасности первых лиц Государства
г) Подтвержденный факт наличия запрещенных средств, нелегальных предметов, лиц находящихся в федеральном розыске/проходящих по уголовному делу в имуществе подозреваемого.
е) Задержание участников преступных организаций, подозреваемых в террористическом акте;
ж) Согласие владельца имущества;
з) Существует угроза жизни или здоровья людей, находящихся в имуществе;
и) Предотвращение совершения преступления, предотвращение утраты улик при достаточно имеющихся на то обстоятельствах.
Статья 6. Понятие и последовательность
6.1. Стадии применения силы - последовательность и классификация возможных законных действий в отношении нарушителя закона со стороны сотрудника правоохранительных ведомств.
6.2. Порядок применения стадий силы:
1) Первая стадия - Присутствие сотрудника правоохранительных органов – эта стадия состоит только из присутствия сотрудника в штатной униформе, возможно с должным образом маркированным средством передвижения (мотоциклом, автомобилем, катером).
Присутствия с очевидной возможностью для объектов понимать присутствие сотрудника полиции, как правило, достаточно для выполнения требований закона и прекращения мелких правонарушений. В зависимости от обстановки и количества людей на месте, этот уровень применения силы может потребовать присутствия нескольких полицейских для уверенного
контроля ситуации.
2) Вторая стадия - Устные требования/команды – ясные и понятные устные распоряжения сотрудника полиции объекту применения силы. В большинстве моделей сотрудник полиции имеет право дополнять свои распоряжения предупреждениями о последствиях за
неисполнение распоряжений, с тем, чтобы улучшить степень кооперативности объекта воздействия. Распоряжения должны быть исполнимыми и законными, а предупреждения должны соответствовать ступеням модели применения силы, в случае отказа объекта выполнять распоряжения. Вероятно, неисполнимым будет, например, требование лицу в инвалидной коляске встать.
3) Третья стадия - Силовое воздействие без спец.средств – К этой стадии относятся заламывание рук, нажатия на болевые точки и обычное применение наручников. На этой стадии существует вероятность нанесения легкого вреда здоровью, но очень мала вероятность причинения тяжкого вреда в виде переломов костей или разрывов связок. Также стадия включает в себя удары руками и ногами, сюда же может относиться применение дубинок. Вероятность нанесения вреда здоровью субъекта в виде переломов, растяжений и разрывов связок.
4) Четвертая стадия - Применение специальных средств – к этой стадии относится применение электрошоковых устройств, водометов, полицейских собак. В некоторых моделях к этому уровню может относиться применение дубинок и слезоточивых аэрозолей. Как правило, специальные средства предназначены для воздействия на мышечную ткань, руки и ноги.
5) Пятая стадия - Смертельная сила – под этой стадией воздействия используется огнестрельное оружие. Однако в этом качестве может выступать и автомобиль, и любое подручное оружие, обладающее необходимыми свойствами. На этой ступени воздействия очень вероятно причинение смерти или нанесение тяжкого вреда здоровью объекта применения силы.
6.3. Стадии применения силы должны соблюдаться в порядке, прописанном в данном кодексе, за исключением ситуаций когда субъект задержания уже нарушил закон или ситуация требует экстренных действий, в таком случае можно перейти к любой стадии без последовательности.
(Пример: вооруженный преступник, угроза жизни человеку/офицеру, отсутствие возможности применить одну из стадий).
Глава V Допрос
Допрос - следственно-розыскное мероприятие, которое проводится на стадии досудебного следствия для получения информации о факте совершения лицом уголовного правонарушения, предусмотренного Уголовным Кодексом. В ходе допроса задаются определённые вопросы, направленные на уточнение и выявления новых фактов об уголовном правонарушении.
Статья 7. Основания для вызова на допрос:
7.1 Основанием для вызова на допрос могут быть:
1) Следствие по делу, досудебное разбирательство
2) Обращение/жалоба в инспекционное управление
3) Лицо так или иначе фигурирует в уголовном/административном деле.
Статья 8. Субъекты допроса
8.1 Субъектами допроса являются:
1) Сотрудники правоохранительных органов, отделов, подразделений, ведущие и/или содействующие следствию.
2) Свидетель, потерпевший, подозреваемый, обвиняемый
3) Адвокат
4) Инспектор офиса Генерального инспектора
Статья 9. Лица уполномоченные к проведению допроса
9.1. Полномочиями на проведения допроса обладают только:
1) Сотрудники инспекционного управления с должности инспектор
2) Сотрудники министерства внутренних дел
Статья 10. Права и обязанности участников допроса
10.1. Свидетель/потерпевший имеет право:
1) Знать по какой причине его вызвали на допрос
2) Присутствовать на допросе со своим адвокатом.
3) Не свидетельствовать против себя и своих близких. Примечание: прямой отказ от дачи показаний, может расцениваться как уклонение от расследования.
4) Обжаловать по окончании допроса незаконные действия сотрудников в отношении себя.
5) Отказаться от допроса в ночное время с 23:00 до 10:00.
6) Хранить молчание.
7) На один телефонный звонок в течение 7-ми минут.
10.2. Подозреваемый/обвиняемый имеет право:
1) Знать в чём он подозревается/обвиняется.
2) Давать объяснения и показания по предъявленным к нему обвинениям, или подозрению в совершении преступления.
3) Пользоваться услугами частного/государственного адвоката.
4) Обжаловать по окончании допроса незаконные действия сотрудников в отношении себя.
5) Отказаться от допроса в ночное время с 23:00 до 10:00.
6) Хранить молчание.
7) На один телефонный звонок в течение 7-ми минут.
10.3. Адвокат имеет право:
1) Единожды требовать 7-ми минутный перерыв во время проведения допроса, с целью скорректировать тактику поведения обвиняемого на допросе.
1.1) Перерыв не идет в счет общего времени проведения допроса.
2) Отказаться от участия в допросе по морально-этическим соображениям с разрешения Генерального инспектора.
3) На приватную беседу с доверителем не более 15-ти минут. Примечание: Перерыв и приватная беседу не идут в счет общего времени проведения допроса.
10.4. Сотрудник проводящий допрос имеет право:
1) Ограничивать свободу перемещения допрашиваемого с целью обеспечения собственной безопасности (использовать наручники).
2) Прерывать/прекращать процедуру допроса в любой момент времени.
3) Обыскивать всех участников допроса, в рамках установленных действующим законодательством с целью собственной безопасности и безопасности субъектов допроса
4) Проверять документы участников допроса
5) Задавать вопросы касающиеся делопроизводства или досудебных разбирательств всем участникам допроса
6) Использовать показания допрашиваемого как доказательства в рамках делопроизводства
7) Использовать все законные методы для обеспечения конфиденциальности полученной в ходе допроса информации
10.5. Допрашиваемый обязан:
1) Максимально ясно и чётко давать показания.
2) Соблюдать устоявшиеся морально-этические нормы общения и поведения.
3) Говорить правду и только правду.
4) Отвечать на все вопросы сотрудника, за исключением вопросов которые напрямую или косвенно не относятся к делопроизводству или досудебному разбирательству или хранить молчание.
Примечание: прямой отказ от дачи показаний, может расцениваться как уклонение от расследования.
10.6. Сотрудник, проводящий допрос, обязан:
1) Убедиться в том, требуются ли субъектам допроса разъяснение их прав, в случае необходимости разъяснить их.
1.1) субъекты допроса вправе потребовать у сотрудника ПО разъяснения его прав, но не более чем 2 раза за весь период процесса задержания.
2) Вести полную видеозапись и аудиозапись допроса (протокол).
2.1) срок хранения протокола допроса составляет 5 суток.
3) Обеспечивать соблюдение прав участников допроса.
Статья 11. Правила проведения допроса
11.1. При проведении допроса должны быть соблюдены следующие правила:
1) Не допускаются угрозы применения физического насилия, а также другие незаконные способы воздействия на допрашиваемого.
2) Все участники допроса должны быть ознакомлены с их правами
3) Время проведения процедуры допроса не должно превышать 40 минут. Исключение: Дальнейшее проведение допроса разрешается с согласием допрашиваемого
Статья 12. Подготовительный порядок к проведения допроса предусматривает действия, обязательные к исполнению следователю к задержанному для проведения дальнейшего допроса.
12.1. Порядок к проведению допроса:
1. Завести задержанного в комнату допроса.
2. Провести полный обыск задержанного лица.
3. Запросить у задержанного документы, которые удостоверяют его личность. В случаях, если документы отсутствуют по любым из причин, уточнить его Фамилию Имя, дату и место рождения и проверить эти данные через внутренние базы данных МВД или ФБР. При необходимости, допускается использование биометрической проверки (например: по отпечаткам пальцев или фотографии).
4. Убедиться, что в комнате допроса ведётся запись (протокол).
5. Представиться задержанному.
6. Объяснить кем задержанный является на допросе. (свидетель/обвиняемый/подозреваемый/потерпевший)
7. Объяснить задержанному его права и обязанности.
12.2. В случае исполнения всех пунктов порядка, следователь имеет право начать процедуру допроса в отношении задержанного.
12.2.1 Сотрудник обязан сказать на запись дату и время начала допроса, по его окончанию - дату и время окончания допроса.
Глава VI Смягчающие и отягчающие обстоятельства.
Статья 13. Смягчающие обстоятельства
Смягчающие обстоятельства - это условия или факторы, которые уменьшают степень вины правонарушителя. Они могут повлиять на решение о смягчении меры ответственности или наказания. Учитываются при назначении наказания.
1) Чистосердечное признание - добровольное признание вины и выражение раскаяния в совершении правонарушения на этапе досудебного расследования, до предъявления официальных обвинений или на ранних стадиях следствия.
2) Активное содействие следствию - оказание существенной помощи правоохранительным органам в раскрытии преступления, сборе доказательств или задержании соучастников.
3) Помощь в раскрытии преступления - любые действия, направленные на облегчение работы следствия и раскрытие других преступлений, связанных с делом.
4) Нарушение правоохранительными органами досудебного расследования - в процессе досудебного расследования были допущены ошибки или нарушения прав гражданина.
5) Нарушение прав граждан в статусе подозреваемого или обвиняемого - любые нарушения прав личности на стадии задержания или следствия.
Статья 14. Отягчающие обстоятельства
Отягчающие обстоятельства - это факторы, которые увеличивают степень вины или тяжесть преступления, влияя на решение суда о мере наказания.
1) Рецидив - совершение повторного преступления после осуждения за аналогичное или иное преступление.
2) Совершение преступления в составе группы лиц по предварительному сговору - преступление совершено несколькими лицами, заранее договорившимися о совместных действиях.
3) Тяжелые последствия преступления - преступление повлекло за собой гибель людей, нанесение серьезного ущерба здоровью или имуществу.
4) Совершение преступления с особой жестокостью - применение чрезмерного насилия или умышленное причинение мучений жертве.
5) Совершение преступления в состоянии алкогольного или наркотического опьянения - данный факт может служить отягчающим обстоятельством, так как такие состояния снижают самоконтроль и увеличивают общественную опасность преступления.
6) Уклонения от следствия и/или суда - попытка избежать ответственности, выразившаяся в скрытии от органов следствия или неявке на судебные заседания.
Глава VII Подписка о невыезде
Подписка о невыезде - это мера пресечения, применяемая в рамках уголовного процесса, которая заключается в обязательстве подозреваемого или обвиняемого не покидать территорию страны без разрешения следователя или суда. Лицо, подписавшее такое обязательство, обязано являться по вызовам следственных органов или суда и не препятствовать расследованию.
Статья 15. Основания для выдачи подписки
5.1 Основанием для выдачи подписки о невыезде является наличие у следственных органов обоснованных подозрений или обвинений в совершении преступления подозреваемым или обвиняемым. При этом учитываются риски уклонения лица от следствия и суда, воспрепятствования расследованию либо совершения иных противоправных действий.
Статья 16. Порядок подписания подписки о невыезде
16.1. Следователь имеет право после допроса подозреваемого или обвиняемого составить и направить в суд ходатайство о подписке о невыезде, если имеются основания полагать, что лицо может уклониться от следствия и суда, воспрепятствовать расследованию или совершить новые преступления. После подачи следователем ходатайства в суд о назначении подписки о невыезде, подозреваемый или обвиняемый должен быть уведомлён о подаче данного ходатайства, а также о возможных последствиях в случае его удовлетворения судом.
16.1.1. Уведомление должно включать информацию о том, что до момента судебного решения подозреваемый не ограничен в праве на передвижение, но после вынесения судебного акта о назначении подписки о невыезде, он обязан будет соблюдать установленные судом ограничения. Следователь обязан разъяснить подозреваемому, что за выезд из страны до или после возможного утверждения судом подписки о невыезде может повлечь за собой более строгие меры пресечения, включая заключение под стражу.
16.2. Ходатайство в суд о назначении подписки о невыезде должно быть подано следователем не позднее чем через 5 часов после уведомления подозреваемого или обвиняемого.
16.3. Подписка о невыезде не вступает в силу до момента её утверждения судом. Суд обязан рассмотреть ходатайство в течение 24 часов с момента его получения. Если суд принимает решение об утверждении подписки о невыезде, она вступает в силу немедленно. В случае отказа суда в удовлетворении ходатайства подписка о невыезде не применяется, а все ранее наложенные временные ограничения автоматически отменяются.
Статья 17. Особые обстоятельства
17.1. Если подозреваемый или обвиняемый покинул территорию Федерации до того, как суд утвердил подписку о невыезде, следователь обязан незамедлительно:
а) Инициировать процедуру розыска лица;
б) Уведомить суд о произошедшем, с указанием, что подозреваемый (обвиняемый) покинул страну.
17.1.1. В таком случае суд, после рассмотрения информации о побеге, может:
а) Выписать ордер AS (Arrest and Search) на имя подозреваемого или обвиняемого;
б) Принять иные меры в соответствии с законодательством.
17.2. Выезд из страны до решения суда может быть расценено как уклонение от следствия и суда и стать основанием для назначения более строгих мер пресечения, включая заключение под стражу.
И утвердится престол милостью, и воссядет на нем в истине, в шатре Давидовом, судия, ищущий правды и стремящийся к правосудию.
Satoshi Nishikiyama, hakushika awayuki и Soshi Awayuki
Глава VIII Повестка
Повестка - это официальный документ, который выдается правоохранительными, надзорными органами, а также судом, с целью уведомить гражданское лицо о необходимости явки в указанное время и место для выполнения определенных действий. Повестка обязывает получателя явиться для проведения следственных мероприятий, допроса, участия в судебном заседании, либо для предоставления показаний или документов.
Статья 18. Виды повесток
18.1. Повестка выданная Министерством внутренних дел - обязывает гражданское лицо явиться в указанное место и время для проведения следственных мероприятий. Такие мероприятия могут включать допрос, очные экспертизы, осмотры, иные процессуальные действия, необходимые для ведения расследования или проверки. Основанием для выдачи повестки служат доказательства или сведения, которые указывают на возможное нарушение законодательства Синей Федерации данным лицом.
18.1.1. Повестка направляется в письменной или электронной форме и должна быть вручена под роспись либо отправлена в личный кабинет на официальном портале Синей Федерации. Электронная подписка должна соответствовать законодательным требованиям и сопровождаться цифровой подписью.
18.1.2. Повестка должна содержать следующую информацию: имя и фамилию (отчество при наличии) лица, которому адресована, описание причин вызова, время и место явки, а также контактные данные уполномоченного лица, к которому можно обратиться для получения дополнительных сведений или предупреждения о невозможности явки.
18.1.3. Неявка по данной повестке может повлечь за собой штрафные санкции, наказание в виде лишения свободы или меры принудительного привода, если гражданское лицо не имеет уважительных причин для неявки. Размер штрафов и порядок их наложения, лишение свободы определяюется в соответствии с административным и уголовным кодексом Синей Федерации. Принудительный привод осуществляется органами внутренних дел.
18.2. Повестка-постановление выданная офисом Генерального инспектора - применяется в случаях, когда требуется провести внутреннее расследование или проверку, касающуюся возможных нарушений законов, норм или внутренних положений служебными лицами или государственными сотрудниками, либо если они могут иметь отношение к расследованию или проверке. Изначально выпускаемые в виде постановления, а после рассылаются на личные адреса.
18.2.1. Повестка-постановление направляется лицу в письменной форме либо через официальный портал в личный кабинет.
18.2.2. Документ должен содержать имя и фамилию (отчество при наличии) лица, которому адресована повестка, описание повода для явки, время и место явки, а также указание на закон, который служит основанием для вызова.
18.2.3. Явка по повестке обязательна. Неявка при отсутствии уважительных причин и предварительного предупреждения может повлечь за собой применение мер принудительного привода и/или лишения свободы.
18.3. Судебная повестка - обязует гражданское лицо или организацию явиться в суд для участия в судебном заседании. Такая повестка может быть направлена как истцу, так и ответчику, а также свидетелям, экспертам и другим участникам процесса, которых суд счел необходимыми для рассмотрения дела. Повестка также может предусматривать предоставление определенных документов или доказательств, необходимых для разрешения дела.
18.3.1. Судебная повестка выдается судом и может быть направлена как в письменной, так и в электронной форме.
18.3.2. Документ включает информацию о судебном деле (номер дела, наименование суда), имя и фамилию (отчество при наличии)или название организации, время, дату и место проведения заседания, а также имя судьи или судебного секретаря, к которому можно обратиться для получения информации.
18.3.3. Неявка на судебное заседание без уважительной причины и предварительного предупреждения может привести к применению мер принудительного привода или штрафам и лишения свободы, а также отложению слушания дела.
Статья 19. Доставка и обжалование повестки
19.1. Способы доставки повестки:
а) Отправка через личный кабинет гражданина на официальном портале Синей Федерации.
б) Личное вручение уполномоченными органами.
19.2. Гражданское лицо вправе обжаловать повестку, если считает её необоснованной. Для этого необходимо обратиться в офис Генерального инспектора в установленном законодательством порядке в течение пяти рабочих дней с момента получения повестки.
19.3. При получении повестки, гражданское лицо вправе запросить у выдающего повестку органу юридическую консультацию для ознакомления со своими правами и обязанностями. Орган, выдавший повестку, обязан предоставить информацию о правах и обязанностях гражданина, либо обеспечить его доступ к правовым консультациям.
Статья 20. Неявка по повестке
20.1. Уважительные причины для неявки по повестке:
а) Заболевание – Если гражданское лицо или его близкий родственник (в случае, если требуется уход) находится на лечении и имеет медицинское заключение, подтверждающее невозможность явки по состоянию здоровья. (( В случае бана ))
б) Несоответствие данных повестки – Если повестка была оформлена с ошибками или не была доставлена надлежащим образом.
в) Заблаговременное уведомление о невозможности присутствия – Если гражданское лицо заранее уведомило органы о невозможности явки и предоставило документы, подтверждающие причину неявки.
г) Иные причины, не предусмотренные в данной главе, не считаются уважительными. Однако могут быть исключительные случаи, когда гражданское лицо имеет основание полагать, что его обстоятельства заслуживают дополнительного рассмотрения. В таких случаях гражданин может обратиться в орган, выдавший повестку, с ходатайством о признании причины уважительной. Решение об удовлетворении такого ходатайства остаётся на усмотрение органа, исходя из специфики представленных данных и обстоятельств. Исключительные случаи должны быть тщательно обоснованы для предотвращения злоупотребления системой вызовов по повесткам.
20.1.1. В случае опоздания на судебное заседание гражданин обязан как можно скорее уведомить суд о причинах задержки. Суд оставляет за собой право перенести заседание или вынести меры ответственности за опоздание в зависимости от обстоятельств.
Глава IX Содержание лиц под стражей в ИВС и СИЗО при правоохранительных органах
Статья 21. Полицейский арест
21.1. Полицейский арест представляет собой краткосрочное содержание лица в изоляторе временного содержания (ИВС) при полицейском департаменте. Целью полицейского ареста является оперативное ограничение свободы лица, подозреваемого в совершении преступления, с целью обеспечения его доступности для проведения дальнейших процессуальных действий и предотвращения возможного уклонения от правосудия или уничтожения доказательств.
21.1.1. Полицейский арест производится на основании ордера AS (Arrest and Search), за исключение ситуаций, когда сотрудник правоохранительных органов вправе задержать лицо без ордера в случаях нахождения его в федеральном розыске (( то есть, у игрока имеется системный розыск )).
21.2. Содержание лица в ИВС не может превышать 48 часов с момента задержания. Если в течение 48 часов при наличии ордера AS обвиняемый не был переведен в СИЗО по решению суда, мера пресечения подлежит снятию.
Статья 22. Оперативное задержание
22.1. ПОперативное задержание представляет собой особую форму полицейского ареста, осуществляемую без ордера AS (Arrest and Search). Данное действие допускается исключительно в ситуациях, когда у сотрудника правоохранительных органов имеются неопровержимые доказательства причастности лица к совершению преступления и существует непосредственная угроза побега подозреваемого или уничтожения им доказательств. При этом оперативное задержание ограничено сроком в 24 часа, в течение которых сотрудник правоохранительных органов обязан получить ордер AS (Arrest and Search). В случае, если ордер не получен, задержанное лицо освобождается.
(( Сотруднику МВД рекомендуется, при возможности, осуществлять РП арест, при котором задержание осуществляется без применения системной команды /arrest. Команда /arrest может использоваться лишь в установленных правилами случаях, когда требуется оперативное задержание.))
Статья 23. Судебный арест
23.1. Судебный арест - это мера пресечения, связанная с длительным ограничением свободы, которая применяется по решению суда на основании ордера PTD (Pre-Trial Detention). В отличие от полицейского ареста, судебный арест предполагает содержание лица в следственном изоляторе (СИЗО), расположенном в исправительном учреждении.
23.1.1. Судебный арест применяется в случаях, когда требуется больше времени для проведения следственных действий или судебных разбирательств, и обеспечивает контроль над лицом, которое может скрыться от следствия или продолжить преступную деятельность. Срок судебного ареста не может превышать 48 часов до момента вынесения судом решение о продлении срока или изменения меры пресечения.
23.1.1.1. Суд вправе продлить срок судебного ареста не более двух раз. Если за это время судебное заседание не было назначено, мера пресечения снимается. В случае, если дата заседания назначена, мера пресечения действует до момента транспортировки лица на суд.
Статья 24. Ордер
24.1. Ордера выписываются и работают в соответствии с Федеральным законом "О государственной системе ордеров"
(( Лица, находящиеся под стражей, не вправе участвовать в РП, способные повлиять на ход расследования, за исключением попыток побега, которые могут быть совершены только в рамках правил. Также лица, находящиеся под стражей, не могут выполнять свои должностные РП обязанности в общем и целом.))]=],
    ['Устав'] = [=[ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ
[1.1] Устав министерства внутренних дел – это свод правил, регулирующих структуру, направление, работу и порядок действия работы министерства внутренних дел.
[1.2] Незнание устава не освобождает сотрудников от ответственности.
[1.3] Вносить изменения в устав министерства внутренних дел уполномочено исключительно лицо, занимающее должность министра.
[1.4] Министр внутренних дел перед внесением изменений обязан закрепить приказом и логом изменения, которые он внес в устав.
[1.5] За нарушение устава Министерства внутренних дел сотрудники могут получить дисциплинарные взыскания от предупреждения вплоть до увольнения с последующим занесением в чёрный список Министерства внутренних дел. Сотрудник, имеющий дисциплинарное взыскание в виде выговора, теряет право на перевод или повышение до его погашения. В случае увольнения сотрудника, имеющего дисциплинарное взыскание в виде выговора или переаттестации, взыскание не аннулируется. Дисциплинарное взыскание считается погашенным только после того, как лицо, объявившее выговор, внесло запись о его аннулировании. Аннулировать выговор может только сотрудник, равный или старший по званию или должности тому, кто объявил выговор.
[1.6] Степень дисциплинарного взыскания по отношению к сотруднику определяет высшее руководство министерства внутренних дел.
[1.7] К дисциплинарным взысканиям относятся:
1) Предупреждение
2) Устный выговор
3) Письменный выговор
4) Строгий выговор
5) Понижение в должности
6) Понижение в спец. звании
7) Переаттестация
8) Увольнение
9) Занесение в черный список
[1.8] Центральный офис Министерства внутренних дел имеет право запросить доказательства нейтрализации, удаления гражданина из базы розыска, ареста, задержания, объявления в розыск, выписки штрафа, изъятия водительских прав, выдачи пропуска в здания МВД, а также любых других процессуальных действий, совершённых в течение последних семи дней. Сотрудник Министерства внутренних дел обязан в течение 24 часов предоставить запрошенные доказательства центральному офису МВД.
[1.8.1] Руководство подразделения имеет право запросить у сотрудника своего подразделения доказательства нейтрализации, удаления гражданина из базы розыска, ареста, задержания, объявления в розыск, выписки штрафа, изъятия водительских прав, выдачи пропуска в здания МВД, а также любых других процессуальных действий, совершённых в течение семи дней.
[1.9] Занимать руководящие должности подразделений PD/PA/SWAT/DB может офицер Полиции в звании "Капитан" и выше или имеющий актуальный диплом о прохождении Полицейского Интенсива Старшего Офицерского Состава, и утвержденный на должность главой Полицейского Департамента или его прямым заместителем путём издания соответствующего нормативно-правового акта.

ГЛАВА II. СТРУКТУРА МВД
[2.1] Структура Министерства внутренних дел разделена на следующие управления и должности:
1) Центральный офис Министерства внутренних дел:
Министр внутренних дел
Первый заместитель Министра
Заместитель Министра по внутренней работе
2) Офис Федерального Бюро Расследований:
Директор ФБР
Первый заместитель Директора ФБР
3) Исправительная колония («Advance Prison»):
Начальник ИК
4) Полицейские департаменты:
Шеф/Комиссар полиции
Заместитель шефа/комиссара
Ассистент шефа/комиссара
Капитан
Лейтенант
Сержант
Офицер II класса
Офицер I класса
Кадет II курса
Кадет I
[2.2] Список имущества Министерства внутренних дел
1) Офис Министерства внутренних дел (Сан-Фиерро)
2) Офис Федерального Бюро Расследований (Сан-Фиерро)
3) Полицейские департаменты (Лос-Сантос, Сан-Фиерро, Лас-Вентурас)
4) Исправительная колония «Advance Prison» (Лос-Сантос)
[2.3] Команда управления министерства внутренних дел обязана следить за доверенным им имуществом, поддерживать ценность и сохранность.
[2.4] Структура отделов полицейских департаментов:
1) Police Academy (PA):
Глава полицейской академии
Заместитель главы полицейской академии
Лектор полицейской академии
2) Patrol Division (PD):
Глава Patrol Division
Заместитель главы Patrol Division
3) Special Weapons and Tactics (SWAT):
Командир SWAT полицейского департамента (Лос-Сантос, Сан-Фиерро, Лас-Вентурас)
Заместитель командира SWAT
[2.5] Структура управлений Федерального Бюро Расследований засекречена и регулируется министром внутренних дел и директором Бюро.

ГЛАВА III. РАБОЧИЙ ГРАФИК
[3.1] Рабочий день в Министерстве внутренних дел начинается в 11:00 и заканчивается в 23:00 независимо от дня.
Исключение: федеральное бюро расследований.
[3.2] В установленные, согласно пункту 5.5 Трудового кодекса, в Синей Федерации праздничные дни, сотрудники МВД заканчивают свой рабочий день раньше на 4 часа. Однако подразделения МВД обязуются сформировать работников для круглосуточного дежурства. Работники, осуществляющие дежурство в праздничный день, получают право на один внеплановый выходной.
[3.3] Министр внутренних дел, его заместитель, руководители полицейских департаментов, директор федерального бюро расследований вправе по необходимости вызвать сотрудников на службу после окончания рабочего дня в случае экстренной ситуации.
[3.4] Министр внутренних дел и его заместитель вправе продлить время рабочего дня в случае экстренной ситуации.
[3.5] Центральный офис МВД, в том числе руководство департаментов, вправе вызвать сотрудника МВД в полицейский департамент, офис ФБР или офис Министерства внутренних дел по объективной причине в любое время суток.
[3.5.1] Агент ФБР вправе вызвать сотрудника Министерства внутренних дел в полицейский департамент, офис ФБР или офис Министерства внутренних дел по объективной причине в любое время суток. Злоупотребление статьёй 3.5.1 действующего Устава МВД или использование её в личных целях запрещено.

ГЛАВА IV. ОБЯЗАННОСТИ СОТРУДНИКОВ МВД
[4.1] Сотрудник министерства внутренних дел может применять должностные полномочия согласно законодательству Синей Федерации, а именно: Уставу МВД, Процессуальному Кодексу, Федеральному закону «О Министерстве Внутренних Дел», Федеральному закону «О Федеральном Бюро Расследований», Федеральному закону «О Юрисдикции», Федеральному закону "О Пенитенциарном учреждении", Федеральному закону «О Чрезвычайном и военном положении», Дорожному кодексу Синей Федерации
[4.2] Сотрудник министерства внутренних дел обязан во время рабочего дня находиться при полной экипировке. Исключение: щит.
[4.3] При выезде в патруль, сотрудник министерства внутренних дел обязан активировать свой GPS-трекер.
[4.4] При окончании рабочего дня, сотрудник министерства внутренних дел обязан сдать вооружение, экипировку и одеться в гражданскую форму, закончив смену.
Исключение: ночная смена.
[4.5] Во время рабочего дня, сотрудник министерства внутренних дел обязан предотвращать, пресекать потенциальные и совершающиеся преступления, правонарушения, совершаемые гражданами Синей Федерации.
[4.6] Помогать гражданам Синей Федерации в случае их обращения, защищать их от преступной деятельности.
[4.7] По требованию гражданина Синей Федерации сотрудник министерства внутренних дел обязан представиться и предъявить своё служебное удостоверение.
[4.8] Во время проведения какого-либо процессуального действия (задержание, наложение штрафа и прочее) по отношению к гражданам Синей Федерации, сотрудник МВД обязан представиться, предъявить своё служебное удостоверение, объяснить причину для проведения процессуального действия.
[4.9] Использовать спец. сигналы, стробоскопы, мегафон для коммуникации с правонарушителем во время активной погони.
[4.10] Сотрудники полицейских департаментов обязаны реагировать на вызовы граждан Синей Федерации для оказания им помощи
Исключение: если в вызове присутствует бред/оскорбления, сотрудник МВД имеет право игнорировать вызов.
[4.11] Сотрудники полицейского департамента обязаны обеспечивать порядок на улицах Синей Федерации, защищать права граждан Синей Федерации, устранять преступность на территории Синей Федерации.
[4.12] Бережно относиться к имуществу министерства внутренних дел: автомобилям, снаряжению и вооружению.
[4.13] Сотрудник министерства внутренних дел обязан иметь видеофиксацию своей деятельности: задержания, аресты, нейтрализации, патрулирование и т.д.
[4.14] Сотрудник министерства внутренних дел обязан реагировать на ситуационные коды, при которых сотрудникам требуется помощь.
[4.15] Подчиняться высшему руководству министерства внутренних дел, директору федерального бюро расследований и его агентуре в случае взятия им руководства на всевозможных спец. операциях, а также Вице-президенту и Президенту Синей Федерации в случае необходимости.
[4.16] Сотрудник министерства внутренних дел в случае использования оружия по отношению к подозреваемому должен иметь видеофиксацию ситуации, а также обязан подать рапорт о нейтрализации, огласив причину в федеральной рации.
[4.17] При объявлении в розыск гражданина Синей Федерации, необходимо указать кодекс, главу, статью, часть статьи (если таковая имеется).
[4.18] В случае, когда сотрудник МВД выписывает штраф гражданину Синей Федерации, необходимо иметь видео доказательства нарушения закона гражданина.
[4.19] При изъятии водительских прав либо при понижении степени водительского удостоверения, необходимо иметь видео-доказательства нарушения закона.
[4.20] Сотрудник Министерства внутренних дел, начиная со звания Офицер I класса обязан завести личное дело в разделе личных дел сотрудников своего департамента (или поднять из архива старое личное дело) строго по установленному формуляру в течение 48 часов с момента вступления в должность. За отсутствие личного дела Офицера по истечении 48 часов с момента вступление в должность Руководство Департамента оставляет за собой право уволить офицера.
[4.21] Сотрудник министерства внутренних дел обязан выкладывать отчетную деятельность в свое личное дело.
[4.22] Руководство подразделения обязано следить за личными делами сотрудников и держать их в порядке: фиксировать дисциплинарные взыскания, служебные награды и записи в личном деле сотрудника.
[4.23] Каждый сотрудник МВД, совершающий процессуальные действия в отношении граждан Федерации (( /clear, /su, /search, /arrest и т.д. )), обязан хранить видео ситуации в течение 7-ми дней. Видеозапись ситуации может запросить на проверку министр внутренних дел или его заместитель, руководитель подразделения сотрудника или его заместитель, а также глава отдела, в котором состоит сотрудник.
[4.24] В случае, если сотрудник МВД был уволен или переведён в другой Департамент - его личное дело должно быть закрыто и перенесено в архив.

ГЛАВА V. ЗАПРЕТЫ СОТРУДНИКОВ МВД
[5.1] Запрещено проявление неадекватного поведения: Сквернословить, обман, розжиг межнациональной розни, расизм, оскорбления, упоминания родных в оскорбительной форме, оскорбление родных, провоцировать, а также разжигать конфликты либо принимать в них участие, использования мата, бранных слов по отношению к сотрудникам МВД, так и по отношению ко всем гражданским лицам без исключений. (( Данная статья устава распространяется в т.ч. на OOC чаты игры. ))
[5.2] Прогуливать рабочий день, построения, тренировки, сборы по приказам уполномоченных лиц.
[5.3] Посещать игорные заведения (казино) и мероприятия, не касающиеся профессиональной деятельности, во время рабочего дня, подрабатывать на различных работах во время рабочего дня. (( участие в мероприятиях от администрации сервера, выполнение /tasks, подработка в Транспортной компании и на системных работах, участие в мероприятии "Семейный кейс" ))
[5.4] Использовать любой транспорт Министерства Внутренних дел в личных целях, использовать спец.сигналы в личных целях, использовать экипировку, вооружение, снаряжение МВД, а также любое имущество принадлежащие МВД в личных и корыстных целях.
[5.5] Привозить, запускать на закрытую территорию полицейского департамента, федерального бюро, офиса министерства внутренних дел посторонних лиц без без разрешения соответствующего руководства.
[5.6] Иметь при себе служебное вооружение и экипировку по окончании рабочего дня.
Исключение: Министр внутренних дел, директор федерального бюро расследований и его агентура, Шефы/Комиссары полиции, сотрудники, работающие в ночную смену.
[5.7] Удалять граждан Синей Федерации из базы федерального розыска за исключением некоторых ситуаций, когда гражданин был объявлен в розыск по ошибке или у него остался GPS-трекер после службы в полиции.
[5.8] Проводить нейтрализацию безоружного человека при побеге, если он не представляет опасности для гражданского населения.
Исключение: если подозреваемый намеренно падает в воду и пытается скрыться от ареста (до момента выхода на сушу).
[5.9] Открывать огонь в общественных местах (( зеленых зонах )), если жизни сотруднику правоохранительных органов или гражданам Синей Федерации ничего не угрожает. Допускается открытие огня в рамках проведения трафик-стопа 10-66.
[5.10] Нарушать юрисдикцию своего департамента за исключением случаев, предусмотренных Федеральным законом «О Юрисдикции»
[5.11] Использовать какие-либо аксессуары в рабочее время.
Исключения: специальные маски для сотрудников специальных подразделений, очки для зрения, солнцезащитные очки чёрного цвета, чёрные кепки, полицейские фуражки, часы, бронежилеты. (( Также разрешены аксессуары, имеющие RP-характер: сигареты, сигары, оружие за спиной. ))
[5.12] Проникать на территорию военных баз, проводить задержания на военных базах, а также на военном объекте «Авианосец»
Исключение: Разрешение руководства военной базы\авианосца. Разрешается присутствие агентов ФБР в маскировке на военных объектах в случае, если того требует расследование.
[5.13] Принимать участие в устранении ЧС на военных базах, авианосце. В случае, если ЧС началось в момент задержания преступника на территории военного объекта с разрешения руководства, сотрудникам следует незамедлительно покинуть территорию военного объекта.
[5.14] Проникать, задерживать преступника, в случае, если на базе/посту отсутствуют сотрудники Мин. обороны.
[5.15] Объявлять в розыск, проводить задержания и обыски людей, которые спят (( AFK более 30 сек, AFK без ESC )).
[5.16] Изымать либо понижать степень водительского удостоверения, будучи далеко от нарушителя (дистанционное изъятие, изъятие во время погони).
[5.17] Оставлять собственные ограждения без присмотра (( /break ))
Исключение: информирование граждан о собеседовании (табличка у входа, которая не мешает проезду/проходу) и установка дополнительного поста (не создающего помеху проезду/проходу; ограждения, необходимые для организации работы МВД на данной точке).
[5.18] Устанавливать ограждения поверх друг друга, строить из них лестницы.
[5.19] В рабочее время нарушать дресс-код.
[5.20] Покрывать своих друзей либо знакомых, предоставлять им какие-либо преимущества перед другими гражданами Синей Федерации, используя свои служебные полномочия.
[5.21] Запрещено объявлять людей в розыск с оскорбительной причиной, матом и любой иной причиной, не предусмотренной законом.
[5.22] Запрещается производить задержания граждан, находясь в патруле под маркировкой Mary. При начале 10-66 в Mary-патруле, требуется вызвать подкрепление и дождаться его, а только потом производить задержание.
[5.23] Игнорирование или неисполнение, а также оспаривание приказов руководства, в том числе во время специальных операций и различных мероприятий.
[5.24] Запрещено производить процессуальные действия в отношении граждан Федерации и их имущества без видеофиксации с датой видеосъёмки. (( без записи видео с /c 60 ))
[5.25] Запрещается присутствие сотрудников МВД на территории логова банды и иных преступных группировок, не имея на то оснований, кроме указанных в пунктах 6.13, 6.14, 6.15, 6.16.
[5.26] На длительное время уезжать из Федерации при исполнении без отпуска или больничного (( отсутствие больше двух недель или низкая активность )).
[5.27] Запрещается проводить оперативно-розыскные мероприятия в одиночку. (( данная формулировка подразумевает соло /wanted на любом патрульном транспорте )).
[5.28] Запрещено игнорирование и неисполнение законного приказа старшего по должности и званию (от 7 порядкового звания и выше), руководства спецопераций и мероприятий, иных уполномоченных лиц.
Исключение: сон в нерабочее время; сотрудник, которому отдан приказ, находится ниже званием, но выше по должностной лестнице.
[5.29] На спецоперациях под руководством агентов ФБР сотрудникам МВД запрещается самодеятельность и нейтрализация без приказа\распоряжения агентов ФБР.
Исключение: Самооборона, ситуации, не терпящие промедления.
[5.30] Запрещено каким-либо образом вмешиваться в работу агентов ФБР во время исполнения ими должностных обязанностей. Злоупотребление статьёй 5.30 действующего Устава МВД или её использование в личных целях запрещено.
Примечание: В случае попытки вмешательства в работу агентов ФБР, агент обязан доказать свою причастность к ФБР и потребовать прекратить вмешательство.

ГЛАВА VI. ПРАВА И ПОЛНОМОЧИЯ СОТРУДНИКОВ МВД
[6.1] Использовать служебный транспорт МВД, спецсигналы, экипировку, вооружение и снаряжение, а также иное имущество МВД в служебных и рабочих целях.
[6.2] Выходить в патруль под маркировкой «Mary» на служебном мотоцикле со звания Офицер I класса.
[6.3] Выходить в патруль под маркировкой «Lincoln» со звания Сержант.
[6.4] Выходить в патруль под маркировкой «Adam« в составе от 2-ух сотрудников со звания Офицер I класса.
[6.5] Производить поиск преступников по базе Федерального розыска (( /wanted )).
[6.6] Проводить различные следственные мероприятия в соответствии с действующим законодательством Синей Федерации.
[6.7] Проводить первичный обыск при задержании гражданина Синей Федерации. Допускается проведение полного обыска на месте задержания в условиях отсутствия опасности для офицера и задержанного лица.
[6.8] Проводить первичный/полный обыск перед определением преступника в исправительную колонию, в ходе проведения следственных мероприятий (допрос).
[6.9] Проводить следственные мероприятия (задержание, обыск, допрос, иные следственно-оперативные мероприятия).
[6.10] Проводить Traffic-Stop 10-55 и 10-66.
[6.11] Уходить в оплачиваемый отпуск, начиная со звания Лейтенант сроком от 5 до 10 дней.
[6.12] Осуществлять внешние и внутренние переводы.
[6.13] Сотрудник ФБР может присутствовать на территории логова банды или другой преступной группировки, находясь в маскировке соответствующей банды, однако в момент работы на территории группировки, сотрудник ФБР должен следовать правилам маскировки: не раскрывать себя и не объявлять в розыск присутствующих на территории логова группировки людям, имея при этом веские основания на работу под прикрытием.
[6.14] Разрешается присутствие сотрудников МВД на территории логова преступной группировки при облаве на неё, если на ту имеются доказательства нелегальной деятельности.
[6.15] Разрешается проведение ареста на территории частного предприятия (( мафии )), однако лишь в случае, когда не доказана причастность этой частной компании к преступному синдикату.
[6.16] Разрешается проведение ареста на территории логова преступной группировки только в том случае, когда во время погони гражданин попытался скрыться на территории банды. При этом сотрудники МВД обязательно должны иметь численное преимущество над членами нелегальных организаций. Строго запрещено заходить в главный дом банды. Если человек на момент начала погони уже находится на территории логова банды, то и ехать за ним запрещено
[6.17] Проживать в опасном районе.
[6.18] Использовать служебную рацию в рабочих целях.
[6.19] Подавать апелляцию министру внутренних дел на пересмотр дисциплинарного взыскания в течение 48 часов с момента выдачи.
[6.20] Проводить задержание не более одного подозреваемого, находясь в LINCOLN-патруле.
[6.21] Выходить в патруль под маркировкой “Henry” со звания “Капитан”.

ГЛАВА VII. СЛУЖЕБНАЯ РАЦИЯ
[7.1] Сотрудникам министерства внутренних дел запрещено говорить в рацию сообщения не по теме, использовать ненормативную лексику (оскорбления, брань, завуалированный мат).
[7.2] Сотрудникам министерства внутренних дел запрещено устраивать рынок по рации, как и на волне собственного подразделения, так на федеральной.
[7.3] Сотрудникам министерства внутренних дел разрешено передавать информацию, используемую в работе по рации.
[7.4] Сотрудникам старшего состава Министерства Внутренних Дел (от 7 порядкового звания и выше) разрешается отдавать законные приказы младшему составу (от 3 до 6 порядкового звания) и кадетам Полицейской Академии.
Исключение: Занимаемая должность сотрудника ниже званием находится выше по должностной лестнице и дает сотруднику полномочия приказывать сотрудникам ниже должностью.
[7.5] Сотрудникам министерства внутренних дел разрешено проводить мини-лекции, сообщать об электронном собеседовании, либо о переводе с соблюдением интервала в 15 минут.
[7.6] Сотрудникам министерства внутренних дел запрещается повторять одно сообщение больше чем три раза.
[7.7] Сотрудникам министерства внутренних дел запрещено устраивать споры, провоцировать людей, неадекватно себя вести. (( Статья устава действует аналогично в OOC чате рации. ))
[7.8] Сотрудникам министерства внутренних дел разрешено использовать федеральную волну со звания Офицер I класса.
Исключение: сотрудники, не достигшие звания Офицер I класса имеют право подключиться к федеральной волне для доноса важной информации, такой как: большое скопление людей/информация о теракте, похищении и других чрезвычайных случаях.
[7.9] Запрещается игнорировать вызовы и сообщения по рации старших по званию и/или должности.
Исключение: сон вне рабочее время.

ГЛАВА VIII. ТАБЕЛЬНОЕ И ОГНЕСТРЕЛЬНОЕ ОРУЖИЕ
[8.1] Полицейский уполномочен на хранение, ношение огнестрельного оружия, а также на его применение и использование.
[8.2] Порядок хранения и ношения огнестрельного оружия, находящегося в распоряжении полицейского, перечень огнестрельного оружия и боеприпасов, используемых в деятельности полиции, и нормы их принадлежности устанавливаются министром внутренних дел Синей Республики.
[8.3] Сотрудник министерства внутренних дел уполномочен применять огнестрельное оружие только после предупреждения о необходимости прекращения противоправных действий.
[8.4] Применение огнестрельного оружия без предупреждения допускается:
1) В случае вооруженного нападения, а также в случае внезапного нападения с применением боевой техники, транспортных средств или других средств, угрожающих жизни или здоровью людей и/или полицейского
2) Если лицо оказывает вооруженное сопротивление
[8.5] Полицейский уполномочен применять огнестрельное оружие только в целях предотвращения или прекращения вооруженного нападения.
[8.6] Полицейский уполномочен применять огнестрельное оружие в случае вооруженного нападения, если предотвращения или прекращения соответствующего нападения невозможно достичь другими средствами.
[8.7] Полицейскому запрещено применять огнестрельное оружие в местах, где может быть нанесен вред другим лицам, а также в огнеопасных и взрывоопасных местах, кроме случаев необходимости отражения нападения или крайней необходимости.
[8.8] Полицейский может взять в руки огнестрельное оружие и привести его в готовность, если считает, что в сложившейся обстановке могут возникнуть основания для его применения.
[8.9] Во время задержания лиц, в отношении которых у полицейского возникло подозрение в совершении тяжкого или особо тяжкого преступления, а также при проверке документов у таких лиц, полицейский может привести в готовность огнестрельное оружие и предупредить человека о возможности его применения, однако применение табельного оружия возможно лишь в случае четкого соответствия правилам нейтрализаций.
[8.10] Полицейский может использовать огнестрельное оружие для подачи сигнала тревоги или вызова вспомогательных сил.
[8.11] Сотрудник Министерства внутренних дел имеет право использовать огнестрельное оружие в автомобильной погоне за подозреваемым с целью самообороны или для стрельбы по колёсам или по корпусу авто с целью остановить транспортное средство внутри которого замечен подозреваемый.

ГЛАВА IX. ТРЕНИРОВОЧНЫЕ МЕРОПРИЯТИЯ
[9.1] Запрещено проводить тренировки, в которых намеренно повреждается государственное имущество и имущество министерства внутренних дел.
[9.2] Запрещено проводить тренировки, в которых используется огнестрельное оружие против других офицеров полиции. При необходимости следует заменять боевые боеприпасы на холостые.
[9.3] Запрещено проводить тренировки в зданиях без ведома и разрешения владельца.
[9.4] Запрещено проводить тренировки, создающие помеху гражданским Синей Федерации.
[9.5] Если тренировка – оцепления здания, то нужно поставить знаки предупреждения на дороге для совершения гражданами объезда территории, на которой проводится тренировка.
[9.6] Любая тренировка затрагивающая глобальное взаимодействие между продразделениями МВД, между другими государственными и частными организациями должна быть обговорена с Министром или его заместителем.

ГЛАВА X. ПЕРЕВОДЫ
[10.1] Переводы осуществляются строго по установленным правилам и со звания Офицер I класса [3].
[10.2] Переводы при наличии дисциплинарных взысканий запрещаются.
[10.3] Переводы осуществляются лишь раз в 10 дней.
[10.4] Для осуществления перевода необходимо пройти испытательный срок на собственном звании.
[10.5] Допускается повышение с трансфером.
[10.6] Переводы осуществляются из подразделения МВД в другое подразделения МВД без потери звания.
[10.7] Заявления на перевод рассматриваются в течение 48-ми часов министром внутренних дел и его заместителем.
[10.8] Переводы в ПД из ФБР осуществляются с прибавлением одного звания к порядковой должности которую агент имеет в Федеральном Бюро Расследований. Исключение: набранный лимит сотрудников в старшем составе и перевод с должности Заместителя директора ФБР.

ГЛАВА XI. ВОССТАНОВЛЕНИЯ
Восстановления в полицейские департаменты:
[11.1] Офицер в отставке имеет право на восстановление по записи в трудовой книге.
[11.2] Срок годности записи в трудовой книжке составляет 6 месяцев;
[11.3] Восстановление происходит из наивысшей должности в записи трудовой книжки в течение шести месяцев с потерей должностей, установленных правилами восстановлений.
[11.4] Восстанавливаться в министерство внутренних дел можно лишь раз раз в 14 дней.
[11.5] Руководящие лица МВД могут отказать в восстановлении если они сомневаются в профессионализме человека, если не нуждаются в людях или набран лимит разрешенных руководящего состава.
[11.6] Все восстановления по трудовой осуществляются исключительно по заявлению.
[11.7] Гражданин имеет право на восстановление в выбранный им департамент на должность Офицер I класса при наличии диплома об окончании полицейской академии или архивированного личного дела в одном из департаментов; cрок годности составляет 6 месяцев.
[11.8] Граждане, имеющие звание Сержант, могут быть восстановлены на звание Офицер I класса при условии, что не истек срок действия восстановления – 6 месяцев.
[11.9] Граждане, имеющие звания Ассистент шефа/комиссара и выше, могут быть восстановлены с потерей трех порядковых званий.
[11.10] Граждане, имеющие звания Капитан и ниже, могут быть восстановлены с потерей двух порядковых званий.
[11.11] Граждане, имеющие запись в трудовой книге о прохождении службы в МВД в спец.звании Шеф/Комиссар/МВД/Директор ФБР, могут быть восстановлены на звание Капитан, но только при том условии, если они успешно отстояли испытательный срок (( лидерский )) на своей должности. В ином случае они могут быть восстановлены с потерей четырех порядковых званий.
Примечание: Граждане, имеющие запись в трудовой книге о нахождении в Федеральном Бюро в пятой порядковой должности и выше могут быть восстановлены на минус 3 должности и при этом необходимо иметь запись в трудовой книге исключительно из ФБР.
[11.12] Граждане, имеющие должность министра внутренних дел, могут быть восстановлены в любое подразделение МВД с потерей трех порядковых званий.
Исключение (к пунктам 11.11 и 11.12): В случае, если граждане имеют запись о нахождении на лидерской должности, однако были сняты досрочно (не достояли срок; не справились, ПСЖ, и т.д.) могут быть восстановлены с потерей четырех порядковых званий.
[11.13] Граждане, поступившие на службу в полицейский департамент, теряют свое право на восстановление для повышения в должности.
[11.14] Сотрудник МВД, уволенный за нарушения уставов, кодексов (включая ситуации, когда сотрудника увольняет вышестоящее руководство (( путем выдачи предупреждения (WARN) )), либо через рассмотрение жалоб) по объективной причине, не может повторно трудоустроиться в МВД (вне зависимости от подразделения) в течение 10 дней с момента увольнения.
Примечание: Дата увольнения сотрудника в вышеуказанных случаях должна быть зафиксирована путем записи в личном деле.
[11.15] Спустя 10 дней с момента увольнения за нарушения уставов, кодексов, сотрудник МВД может трудоустроиться в МВД, однако прохождение академии и предыдущее звание не учитывается.
Исключение: Сотрудники МВД находящиеся в Белом списке.
[11.16] Заявления на восстановления рассматривает министр внутренних дел и его заместитель в течение 48-ми часов.
[11.17] Граждане, находящиеся в Белом Списке МВД третьей степени, могут быть восстановлены на седьмую порядковую должность в любое подразделение МВД.
[11.18] Граждане, находящиеся в Белом Списке МВД второй степени, могут быть восстановлены на восьмую порядковую должность в любое подразделение МВД.
[11.19] Граждане, находящиеся в Белом Списке МВД первой степени, могут быть восстановлены на девятую порядковую должность в любое подразделение МВД.

Восстановления в ФБР:
[11.20] Граждане, имеющие запись в трудовой о нахождении в федеральном бюро 5-10 порядковой должности, могут быть восстановлены с потерей трех порядковых должностей, при этом необходимо иметь запись в трудовой книге исключительно из ФБР срок которой не превышает 6 месяцев с момента увольнения.
[11.21] Граждане, проходившие национальную академию ФБР и имеющие личное дело сотрудника/личное дело студента или другие подтверждения этому, могут восстановиться на должность Младший агент (3) если не прошло 6 месяцев с момента увольнения.

ГЛАВА XII. ПОЛИЦЕЙСКАЯ АКАДЕМИЯ
[12.1] Шефы/Комиссары департаментов и их первые заместители имеют полномочия на назначение Главы полицейской академии.
[12.2] Глава полицейской академии имеет право отправить сотрудника своего департамента на переаттестацию в полицейскую академию, если есть доказательства его нарушения устава МВД и/или нарушения действующего законодательства.
[12.3] После успешного прохождения переаттестации сотруднику возвращается звание, с которого он был понижен.
[12.4] Кадет Полицейской академии не является полноправным сотрудником Министерства внутренних дел, следовательно, не имеет права на осуществление какой-либо деятельности офицера полиции/агента ФБР.
[12.4.1] Нарушение статьи 12.4 кадетом Полицейской академии влечёт за собой дисциплинарное взыскание вплоть до занесения в ЧС МВД в зависимости от тяжести нарушения.
[12.4.2] Кадет Полицейской Академии имеет право иметь при себе личное оружие, приобретенное по лицензии, и применять его в целях самообороны в том случае, если есть возможность доказать правомерность применения личного оружия в целях самообороны путём видеофиксации.
[12.5] Программу обучения имеет право регулировать только министр внутренних дел.
[12.6] Несоблюдение программы обучения кадетов со стороны руководства полицейской академии карается дисциплинарными взысканиями вплоть до увольнения из министерства внутренних дел.
[12.7] Для подачи заявления в полицейскую академию даются 24 часа. Если кадет не успевает подать заявку по уважительным причинам, он обязан сообщить об этом руководству. Примечание: кадет считается зачисленным с момента создания его личного дела. Если кадет не успевает подать заявку на зачисление в течение 24 часов без уважительной причины, он отчисляется из академии.
[12.8] На прохождение полицейской академии дается 3 дня с момента получения формы Департамента Полиции. Если кадет не успевает пройти академию по уважительным причинам, то он обязан сообщить об этом руководству. Примечание: Если кадет не успевает за 3 дня без уважительной причины, то руководство оставляет за собой право уволить его.
[12.9] При выпуске студентов из полицейской академии, руководство ПА обязано вручить студенту диплом об успешном прохождении полицейской академии (( /show )).

ГЛАВА XIII. ЧЕРНЫЙ СПИСОК
[13.1] Министерство внутренних дел имеет единый реестр черного списка.
[13.2] Регламент черного списка определяется и реформируется министром внутренних дел.
[13.3] Все основные условия и правила черного списка находятся в специальном интернет ресурсе министерства внутренних дел.
[13.4] Заявления на внесения и вынос из черного списка проверяются в течение 48-ми часов исключительно министром внутренних дел.
[13.5] Заявления на внесение в черный список разрешено составлять любому гражданину Синей Федерации.
[13.6] Министр внутренних дел имеет право отказать заявления на внесение в черный список, если посчитает доказательственную базу недостаточной для занесения в черный список.
[13.7] Министр внутренних дел при реформировании системы черного списка имеет право амнистировать I и II степень черного списка.
[13.8] При повторном попадании в черный список любой степени, сотрудник автоматически переводиться III степень черного списка без права на вынос.

ГЛАВА XIV. ЖАЛОБЫ НА СОТРУДНИКОВ
[14.1] Директор ФБР/Шеф/Комиссар департамента обязан иметь специальный интернет-ресурс для подачи жалоб на сотрудников.
[14.2] Жалобы на сотрудников рассматривает исключительно Директор ФБР/Шеф/Комиссар и их прямые заместители.
[14.3] При несогласии сотрудника с вердиктом Директора ФБР/Шефа/Комиссара, сотрудник имеет право подать заявление на апелляцию министру внутренних дел.
[14.4] Директор ФБР/Шеф/Комиссар обязаны рассматривать жалобы от граждан штата в течение 24-ех часов.
[14.5] Шефам/Комиссарам департаментов запрещено менять критерии подачи жалоб на сотрудников.
[14.6] Единые критерии для подачи жалоб на сотрудников:
1) Жалобы могут рассматриваться министром внутренних дел до 48 часов с момента подачи
2) Срок годности доказательств на нарушение офицера 5 дней (включая день совершения нарушения)
3) Подать жалобу может только гражданин, в отношении которого было совершено правонарушение (исключение: юридически доверенное лицо)
4) Доказательственную базу могут составлять только оригинальные (( без монтажа и музыки )) видеозаписи хорошего качества (( 480p/720p )), с отчётливым нарушением офицера полиции (( /c 060 ))
5) Жалоба должна соответствовать стандарту формы подачи письменной жалобы, утверждённой министром внутренних дел (есть исключения)
6) За дачу неверных сведений/обмана/подделки материалов предусмотрена уголовная ответственность
7) Жалоба подаваемая на сотрудника Министерства внутренних дел должна быть корректно оформлена. (( без использования MG в IC теме ))
Нажмите, чтобы раскрыть...
[14.7] В случае, если на сотрудника МВД была подана жалоба с признаками нарушения законодательства (не устава), то в таком случае жалоба должна быть отказана, а человеку, подавшему жалобу, сообщено, чтобы тот обратился в офис Генерального инспектора.

ГЛАВА XV. ДРЕСС-КОД
ДРЕСС-КОД:

Спойлер: Дресс-код


[15.4] Для центрального офиса Министерства внутренних дел (иначе именуемое как высшее руководство МВД) дресс-код остается свободным, однако он должен быть официально-делового стиля. Примечание: центральный офис Министерства внутренних дел имеет право использовать весь доступный Уставом дресс-код МВД включая ФБР.
[15.5] Для сотрудников федерального бюро расследований дресс-код остается свободным, однако он должен быть официально-делового стиля. Сотрудники Федерального Бюро Расследований имеют право использовать форму под номером 285 и 287 для выполнения оперативной деятельности, осуществления оперативно-розыскных мероприятий и иной деятельности по личному усмотрению агента ФБР.
[15.6] Для руководства полицейских департаментов в лице Шефа/Комиссара и его первого заместителя дресс-код остаётся свободным, однако он должен быть официально-делового стиля.
[15.7] Для Начальника Исправительной Колонии [Пенитенциарного Учреждения] дресс-код остается свободным, однако он должен быть официально-делового стиля.
[15.8] Для руководства Детективного бюро и его сотрудников дресс-код остаётся свободным, однако он должен быть официально-делового стиля.

ГЛАВА XVI. НЕЙТРАЛИЗАЦИИ
[16.1] Каждый сотрудник младшего состава Министерства внутренних дел по окончании рабочего дня обязан оставить рапорт о произведённых нейтрализациях в соответствующем интернет-ресурсе своего департамента.
[16.1.1] Сотрудники полицейского департамента находящиеся на званиях лейтенант-заместитель шефа/комиссара включительно, освобождаются от ежедневной публикации доказательств на совершённые им в этот день нейтрализации. При этом сотрудник полиции обязан иметь видеофиксацию произошедшего.
[16.2] Шеф/Комиссар департамента обязан отслеживать подачу рапортов о нейтрализации от своих сотрудников.
[16.3] Если офицер не оставил рапорт в течение 24 часов, то он подвергается строгим мерам дисциплинарных взысканий от выговора плоть до понижения и увольнения из министерства внутренних дел.
[16.4] Систематические отсутствие нескольких нейтрализаций по истечении 24 часов влечёт за собой дисциплинарное взыскание в виде увольнения из рядов Министерства внутренних дел.

ГЛАВА XVII. ИСПЫТАТЕЛЬНЫЕ СРОКИ
[17.1] Испытательный срок – это период времени, в течение которого сотрудник МВД обязан проявить свою квалифицированность и пригодность к должности, которую он занимает.
[17.2] В течение испытательного срока сотрудник МВД:
1) Не вправе совершить перевод внутренний/внешний в другое подразделение либо же в организацию
2) Не может быть повышен во время испытательного срока в звании, или назначен на новую должность
3) Не может уйти в отпуск до истечения испытательного срока
[17.3] Сотрудник МВД, прошедший онлайн-собеседование в старший состав подразделения, не вправе быть повышен до окончания испытательного срока.
[17.4] Обязательные испытательные сроки сотрудников министерства внутренних дел:
Полицейские департаменты:
(( 1 )) Кадет I курса –1 день
(( 2 )) Кадет II курса – 1 день
(( 3 )) Офицер I класса – 1 день
(( 4 )) Офицер II класса – 2 дня
(( 5 )) Сержант – 2 дня
(( 6 )) Лейтенант – 3 дня
(( 7 )) Капитан – 4 дня
