[18.3] Ситуационные коды (CODE):
CODE 0 – Максимальный приоритет: офицер(ы) в критическом положении. Все юниты обязаны немедленно выдвигаться.
CODE 1 – Офицер в бедственном положении, вторая по срочности категория.
CODE 1-1 – Выезд с гаража.
CODE 1-3 – Уход с патруля (указать причину).
CODE 1-4 – Перевозка задержанного в департамент.
CODE 2 – Поддержка в тихом режиме (без сирен).
CODE 3 – Экстренный вызов, выезд на месте с сиренами.
CODE 4 – Ситуация под контролем, справляемся самостоятельно.
CODE 5 – Поддержка от ближайших патрулей.
CODE 6 – Офицерам держаться подальше от опасного района (указать место).
CODE 7 – Обеденный перерыв (указать место остановки).
CODE 8 – Требуется медицинская помощь (указать локацию и код).
CODE 9 – Необходимо выставить оцепление (указать локацию).
CODE 21 – Преступник нейтрализован.
