ГЛАВА XIX. ЮРИСДИКЦИЯ
[19.1] Юрисдикция - это определенная территория, на которой сотрудники департамента имеют правовую силу, определенная данным нормативно-правовым актом и наделенная полномочиями в соответствии с Федеральным Законом "О Юрисдикции". За пределами юрисдикции своего департамента офицер не имеет права осуществлять свою деятельность, каждый сотрудник департамента юстиции обязан соблюдать юрисдикцию.
При нарушении юрисдикции каждый офицер департамента обязан в общую волну (( /f )) доложить об этом департаменту, юрисдикцию которого он нарушает.
[19.2] Данное положение регламентировано в соответствии с Федеральным Законом "О Юрисдикции" и Федеральным Законом "О Министерстве Внутренних Дел".
[19.3] Соблюдение правил юрисдикции организации обязательно для всех сотрудников, находящихся на дежурстве. Нарушение юрисдикции при отсутствии разрешения влечёт уголовную и внутриорганизационную ответственность, поскольку юрисдикция регламентирована законами Синей Федерации «О юрисдикции», а также действующим Уставом.
[19.4] Для каждого из подразделений существует своя отдельно закрепленная юрисдикция:
LSPD - ш. Los Santos(город и близлежащая территория)
SFPD - ш. San Fierro(город и близлежащая территория)
LVPD - ш. Las Venturas(город и близлежащая территория)
FBI; SWAT; DB - подразделения, имеющие федеральную юрисдикцию(утверждено законами и нормативно-правовыми актами)
Высшее руководство Министерства внутренних дел, руководители подразделений (шефы, директор Федерального бюро расследований), начальник исправительной колонии и первые заместители руководителей подразделений также имеют федеральную юрисдикцию.
Спойлер: Карта юрисдикций
[19.5] Нарушение юрисдикции позволяется с разрешения руководителя подразделения(Шефа департамента, как со стороны нарушаемой юрисдикции, так и со стороны нарушившей юрисдикции) и Высшего Руководства Министерства Внутренних Дел.
[19.6] Нарушение юрисдикции своего департамента также считается законным в следующих случаях:
а) Погони за лицом, нарушившее действующее законодательство;
б) Межведомственные спец.операции и тренировочные мероприятия;
в) Исполнения распоряжений, обязательств или предписаний, возложенных нормативным правовым актом Министерства Внутренних Дел и/или Генеральной инспекцией;
г) Единоличного или совместного с другими государственными структурами осуществления государственных поставок;
д) Планового открытия юрисдикции с 22:00 до 10:00 ежедневно;
е) Введение чрезвычайного или военного положения.]=],

