        return
    end
    commandSu(id .. ' 6 2.1 УК')
end

local function commandSmartWanted(args)
    local id, query = trim(args):match('^(%d+)%s*(.*)$')
    local validId, _, err = getPlayerById(id)
    if not validId then notify(err or 'Использование: /sus [ID] [поиск]'); return end
    selectorTargetId = validId
    setBuffer(wantedQueryBuf, ffi.sizeof(wantedQueryBuf), trim(query))
    wantedSelector[0] = true
    ticketSelector[0] = false
end

local function commandTicket(args)
    local id, amount, reason = trim(args):match('^(%d+)%s+(%d+)%s+(.+)$')
    amount = tonumber(amount)
    if not id or not amount or amount < 1 then
        notify('Использование: /ticket [ID] [сумма] [причина]')
        return
    end
    runSequence('Оформление штрафа', {
        '/me достал бланк штрафной квитанции и ручку.',
        '/me заполнил сведения о нарушителе, сумму и основание штрафа.',
        '/do В квитанции указаны сумма {cmd_amount}$ и причина: {cmd_reason}.',
        '/ticket {id} {cmd_amount} {cmd_reason}'
    }, { targetId = tonumber(id), tokens = { ['{cmd_amount}'] = amount, ['{cmd_reason}'] = trim(reason) } })
end

function commandQuickOncomingTicket(args)
    local id = trim(args):match('^(%d+)$')
    if not id then
        notify('Использование: /vstr [ID] – 2.7 АК, штраф 25.000$.')
        return
    end
    commandTicket(id .. ' 25000 2.7 АК')
end

local function commandSmartTicket(args)
    local id, query = trim(args):match('^(%d+)%s*(.*)$')
    local validId, _, err = getPlayerById(id)
    if not validId then notify(err or 'Использование: /tick [ID] [поиск]'); return end
    selectorTargetId = validId
    setBuffer(ticketQueryBuf, ffi.sizeof(ticketQueryBuf), trim(query))
    ticketSelector[0] = true
    wantedSelector[0] = false
end

