local function commandM55()
    if not getCharVehicleSafe(PLAYER_PED) then
        notify('Для использования мегафона сядьте в служебный транспорт.')
        return
    end
    refreshPatrolData()
    local targetVehicle = getNearestVehicle(80.0)
    local driverAddress = targetVehicle and getVehicleMegaphoneAddress(targetVehicle)
        or 'Водитель автомобиля'
    local lines = {
        radioPrefix() .. "{surname_self} на CONTROL. Провожу '55 в районе {location}, С'4, недоступен."
    }
    if targetVehicle then lines[#lines + 1] = radioPrefix() .. '{target_report}' end
    lines[#lines + 1] = '/m Внимание! {target_driver}!'
    lines[#lines + 1] = '/m Прижмитесь к обочине и заглушите двигатель.'
    lines[#lines + 1] = '/m Оставайтесь в автомобиле, держите руки на руле и ожидайте.'
    runSequence('Мегафон 10-55', lines, { tokens = {
        ['{target_driver}'] = driverAddress,
        ['{target_report}'] = getVehicleRadioReport(targetVehicle)
    } })
end

