    imgui.EndChild()
    imgui.Dummy(imgui.ImVec2(0, 5))
end

function drawCenteredTabs(labels, selected, idPrefix, width)
    width = width or 135
    local spacing = imgui.GetStyle().ItemSpacing.x
    local totalWidth = #labels * width + (#labels - 1) * spacing
    local windowWidth = imgui.GetWindowWidth()
    local padding = imgui.GetStyle().WindowPadding.x
    local startX = math.max(padding, (windowWidth - totalWidth) * 0.5)
    imgui.SetCursorPosX(startX)
    local result = selected
    for index, title in ipairs(labels) do
        local active = selected == index
        if active then
            imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.18, 0.43, 0.72, 1.0))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.24, 0.52, 0.84, 1.0))
        end
        if imgui.Button(u8(title .. '##' .. idPrefix .. index), imgui.ImVec2(width, 32)) then result = index end
        if active then imgui.PopStyleColor(2) end
        if index < #labels then imgui.SameLine() end
    end
    imgui.Dummy(imgui.ImVec2(0, 4))
    return result
end

local function drawCommands()
    drawPageHeader('Команды', 'Серверные возможности и автоматизированные RP-команды PoliceHelper')
    commandListMode = drawCenteredTabs({ 'Серверные команды', 'Команды PoliceHelper' }, commandListMode, 'commandMode', 230)
    imgui.Spacing()
    local interviewButtonWidth = 300
    local interviewButtonStartX = imgui.GetCursorPosX()
    local interviewButtonArea = imgui.GetContentRegionAvail().x
    imgui.SetCursorPosX(interviewButtonStartX + math.max(0, (interviewButtonArea - interviewButtonWidth) * 0.5))
    if imgui.Button(u8'Открыть мастер собеседования', imgui.ImVec2(interviewButtonWidth, 30)) then
        commandInterview('')
    end
    imgui.SetCursorPosX(interviewButtonStartX)
    imgui.Spacing()
    imgui.Separator()
    imgui.Spacing()
    imgui.BeginChild('##stableCommandList', imgui.ImVec2(0, 0), false)
    local sections = commandListMode == 1 and serverCommandSections or helperCommandSections
    for index, block in ipairs(sections) do
        imgui.SetNextItemOpen(true, imgui.Cond.Once)
        if imgui.CollapsingHeader(u8(block.title .. '##commandBlock' .. index)) then
            drawDetailedCommandRows(block.rows, '##commandColumns' .. commandListMode .. '_' .. index)
            imgui.Dummy(imgui.ImVec2(0, 7))
        end
    end
    imgui.EndChild()
end

